{
  "cvars": {
    "ivs": [
      {
        "description": "Instructor physical attractiveness as rated by a panel of judges (standardized). Higher values indicate more attractive instructors.",
        "columns": [
          "beauty_z"
        ]
      }
    ],
    "dv": {
      "description": "Student overall teaching evaluation score (course-level mean rating, 1-5).",
      "columns": [
        "eval"
      ]
    },
    "controls": [
      {
        "description": "Instructor gender (1 = female, 0 = male). Included as a demographic control.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "gender_female"
        ]
      },
      {
        "description": "Instructor age in years (numeric).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "age"
        ]
      },
      {
        "description": "Instructor minority status (1 = non-Caucasian/minority, 0 = non-minority).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "minority_yes"
        ]
      },
      {
        "description": "Tenure track status (1 = on tenure track / yes, 0 = no).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "tenure_yes"
        ]
      },
      {
        "description": "Native English speaker (1 = yes, 0 = no).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "native_yes"
        ]
      },
      {
        "description": "Course credit type (1 = single-credit elective, 0 = more credits).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "credits_single"
        ]
      },
      {
        "description": "Course division indicator (1 = upper-division, 0 = lower-division).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "division_upper"
        ]
      },
      {
        "description": "Class size (number of students who participated), standardized to mean 0 and SD 1.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "students_z"
        ]
      },
      {
        "description": "Quadratic term for beauty to capture potential non-linear effects (beauty_z squared).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "beauty_z2"
        ]
      },
      {
        "description": "Professor identifier used only for clustering standard errors (not a model covariate).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "prof"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"\n    Transform the raw Hamermesh classroom dataset into the analysis dataframe.\n\n    Outputs (keeps/creates columns used by the model):\n      - eval: dependent variable (kept)\n      - beauty_z: standardized beauty score (mean 0, sd 1)\n      - beauty_z2: squared beauty_z to capture nonlinearity\n      - gender_female: 1 if female, 0 if male\n      - age: numeric age (kept)\n      - minority_yes: 1 if minority == 'yes', 0 if 'no'\n      - tenure_yes: 1 if tenure == 'yes', 0 if 'no'\n      - native_yes: 1 if native == 'yes', 0 if 'no'\n      - credits_single: 1 if credits == 'single', 0 otherwise\n      - division_upper: 1 if division == 'upper', 0 otherwise\n      - students_z: standardized students count (mean 0, sd 1)\n      - prof: professor id (kept for clustering)\n\n    Missing values in key columns (eval, beauty) are dropped. Categorical mappings handle unexpected values by treating them as NaN and then filling with 0 where appropriate.\n    \"\"\"\n    df = df.copy()\n\n    # Drop rows with missing outcome or main predictor\n    df = df.dropna(subset=['eval', 'beauty'])\n\n    # Standardize beauty\n    beauty_mean = df['beauty'].mean()\n    beauty_std = df['beauty'].std(ddof=0)\n    if beauty_std == 0 or np.isnan(beauty_std):\n        df['beauty_z'] = 0.0\n    else:\n        df['beauty_z'] = (df['beauty'] - beauty_mean) / beauty_std\n\n    # Quadratic term for potential non-linear relationship\n    df['beauty_z2'] = df['beauty_z'] ** 2\n\n    # Binary indicators for categorical controls\n    # Map expected categories to 1/0; unknown values -> NaN -> fill with 0\n    df['gender_female'] = df['gender'].map({'female': 1, 'male': 0})\n    df['gender_female'] = df['gender_female'].fillna(0).astype(int)\n\n    df['minority_yes'] = df['minority'].map({'yes': 1, 'no': 0}).fillna(0).astype(int)\n    df['tenure_yes'] = df['tenure'].map({'yes': 1, 'no': 0}).fillna(0).astype(int)\n    df['native_yes'] = df['native'].map({'yes': 1, 'no': 0}).fillna(0).astype(int)\n    df['credits_single'] = df['credits'].map({'single': 1, 'more': 0}).fillna(0).astype(int)\n    df['division_upper'] = df['division'].map({'upper': 1, 'lower': 0}).fillna(0).astype(int)\n\n    # Age: ensure numeric, drop or coerce non-numeric\n    df['age'] = pd.to_numeric(df['age'], errors='coerce')\n\n    # Class size: standardize 'students' (number who participated in evaluation)\n    df['students'] = pd.to_numeric(df['students'], errors='coerce')\n    students_mean = df['students'].mean()\n    students_std = df['students'].std(ddof=0)\n    if students_std == 0 or np.isnan(students_std):\n        df['students_z'] = 0.0\n    else:\n        df['students_z'] = (df['students'] - students_mean) / students_std\n\n    # Keep professor id for clustering; ensure it's numeric\n    df['prof'] = pd.to_numeric(df['prof'], errors='coerce')\n\n    # Final: drop any rows that have become missing in required controls (if any)\n    required_cols = ['eval', 'beauty_z', 'beauty_z2', 'gender_female', 'age', 'minority_yes',\n                     'tenure_yes', 'native_yes', 'credits_single', 'division_upper', 'students_z', 'prof']\n    df = df.dropna(subset=required_cols)\n\n    # Return the dataframe with the required columns (and keep other columns if user wishes)\n    return df\n",
  "m_code": "def model(df: pd.DataFrame):\n    \"\"\"\n    Estimate the effect of instructor beauty on student evaluations.\n\n    Model: OLS regression of eval on standardized beauty (linear and quadratic) plus controls.\n    Standard errors are clustered by professor ('prof') to account for non-independence across courses taught by the same instructor.\n\n    Returns the fitted statsmodels regression results object with cluster-robust SEs applied.\n    \"\"\"\n    import statsmodels.formula.api as smf\n\n    # Formula: main effect of beauty (linear and quadratic) plus controls\n    formula = (\n        'eval ~ beauty_z + beauty_z2 + gender_female + age + minority_yes + '\n        'tenure_yes + native_yes + credits_single + division_upper + students_z'\n    )\n\n    # Fit OLS with cluster-robust standard errors by prof\n    ols_model = smf.ols(formula=formula, data=df)\n    # statsmodels allows passing cov_type='cluster' to fit(); groups provided in cov_kwds\n    results = ols_model.fit(cov_type='cluster', cov_kwds={'groups': df['prof']})\n\n    # Return the fitted results object. Caller can inspect .summary(), .params, .bse, etc.\n    return results\n"
}
